// Source: src/core/experience-state.js
/* Bimi v2: a ProCredit-inspired, independent banking concept. All actions stay in this browser. */
'use strict';
Object.assign(icons,{search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',close:'M6 6l12 12M6 18L18 6',swap:'M4 7h15l-4-4M20 17H5l4 4',copy:'M8 8h13v13H8zM16 8V3H3v13h5',calendar:'M4 5h16v16H4zM8 2v6m8-6v6M4 11h16',message:'M3 3h18v14H8l-5 4zM7 8h10m-10 4h7',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18',store:'M3 10h18l-2-7H5zM4 10v11h16V10M9 21v-7h6v7',building:'M4 22V3h12v19M8 7h4m-4 4h4m-4 4h4M16 10h4v12M8 22v-3h4v3',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z'});
let hideBalances=false,transferTab='send',loanView='hub',activityFilter='all',activityQuery='',activityFrom='',activityTo='',accountTab='everyday';
const titles={dashboard:'Overview',accounts:'My accounts',transfers:'Payments & transfers',cards:'My cards',loans:'Loans',activity:'Activity',support:'Help & support'};
const navItems=[['dashboard','home','Overview'],['accounts','wallet','Accounts'],['transfers','send','Payments'],['cards','card','Cards'],['loans','loan','Loans'],['activity','history','Activity']];
const masked=n=>hideBalances?'€ ••••••':money(n);
const initials=n=>esc(n.split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join(''));
function ensureState(){
 if(!state.v2){state.v2=true;state.beneficiaries=[{name:'Arben Berisha',iban:'XK050000000000000001',color:'peach'},{name:'Drita Gashi',iban:'XK050000000000000002',color:'lavender'},{name:'Luan Krasniqi',iban:'XK050000000000000003',color:'mint'}];state.requests=[];state.messages=[];state.paidBills=[];state.preferences={notifications:true,compact:false};
 const history=[['2026-09-21','Monthly salary',1850,'Salary'],['2026-09-22','Apartment rent',-425,'Home'],['2026-09-24','Viva Fresh',-74.8,'Shopping'],['2026-09-28','KESCO',-59.2,'Bills'],['2026-08-21','Monthly salary',1850,'Salary'],['2026-08-23','Apartment rent',-425,'Home'],['2026-08-25','Viva Fresh',-92.3,'Shopping']];state.tx.push(...history.map((t,i)=>({id:'SAMPLE-'+i,date:t[0],name:t[1],amount:t[2],desc:t[3]+' · sample history',category:t[3],kind:t[2]>0?'in':'out'})));
 }
 state.beneficiaries??=[];state.requests??=[];state.messages??=[];state.paidBills??=[];state.preferences??={notifications:true};
}

// Source: src/core/navigation.js
function render(){ensureState();if(logged&&page==='loans'&&loanView==='application'&&loanStage<6)state.loanDraft={loan:{...loan},stage:loanStage};if(loanStage===6&&loanView==='application')state.loanDraft=null;document.getElementById('root').innerHTML=logged?shell():auth();bind();if(logged)save();}
function goto(p){closeDialog();page=p;transferStage=0;transfer=null;if(p==='loans')loanView='hub';render();window.scrollTo(0,0);$('#main h1')?.focus({preventScroll:true});}
function pagehead(title,sub,action=''){return `<div class="pagehead"><div><div class="eyebrow muted">PERSONAL BANKING · KOSOVO</div><h1 tabindex="-1">${title}</h1><p>${sub}</p></div>${action}</div>`}
function shell(){return `<a class="skip-link" href="#main">Skip to content</a><div class="shell"><aside class="sidebar">${brand()}<div class="workspace-label"><span class="workspace-indicator"></span>Personal workspace ${icon('chevron')}</div><div class="nav-label">EVERYDAY BANKING</div><nav class="nav" aria-label="Main navigation">${navItems.map(([p,i,n])=>`<button class="${page===p?'active':''}" ${page===p?'aria-current="page"':''} onclick="goto('${p}')">${icon(i)}<span>${n}</span>${p==='loans'?'<span class="badge">Digital</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-tip"><div class="roundicon">${icon('shield')}</div><strong>Your banking, simplified.</strong><p>One place for your everyday finances and your next big step.</p><span class="mini-demo">INDEPENDENT CONCEPT</span></div><button class="side-help ${page==='support'?'active':''}" onclick="goto('support')">${icon('help')} Help & support ${icon('chevron')}</button><button class="side-profile" onclick="profileDialog()"><span class="avatar">${initials(state.name)}</span><span><strong>${esc(state.name)}</strong><small>View profile & settings</small></span>${icon('settings')}</button></div></aside><div class="workspace"><header class="topbar"><div class="row"><span class="mobile-brand">bimi<span>.</span></span><span class="breadcrumb muted">Personal <span class="crumb-divider">/</span> <strong>${titles[page]||'Overview'}</strong></span></div><div class="row top-actions"><button class="icon-button" aria-label="Open step-by-step guide" onclick="journeyGuide()">${icon('help')}</button><span class="concept-tag"><span></span>Concept demo</span><button class="icon-button search-button" aria-label="Search banking services" onclick="searchDialog()">${icon('search')}</button><button class="icon-button notification-button" aria-label="Open notifications" onclick="notificationsDialog()">${icon('bell')}<i></i></button><span class="top-separator"></span><button class="profile-btn top-profile row" onclick="profileDialog()"><span class="avatar">${initials(state.name)}</span><span><strong>${esc(state.name.split(' ')[0])}</strong><small>Personal account</small></span></button></div></header><main class="main" id="main">${page==='dashboard'?dashboard():page==='accounts'?accounts():page==='transfers'?transfers():page==='cards'?cards():page==='loans'?loans():page==='support'?support():activity()}<footer class="footer"><span>Bimi · ProCredit-inspired design concept. Not affiliated with ProCredit Bank.</span><span>${icon('lock')} Fictional data · Simulated transactions & signatures</span></footer></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${navItems.filter(x=>x[0]!=='accounts').map(([p,i,n])=>`<button class="${page===p?'active':''}" onclick="goto('${p}')">${icon(i)}${n==='Overview'?'Home':n}</button>`).join('')}</nav></div>`}

// Source: src/features/auth.js
function auth(){return `<div class="auth"><section class="auth-story">${brand()}<div class="auth-copy"><span class="eyebrow">BANKING, MADE HUMAN.</span><h1>Life moves.<br>Your bank<br><em>moves with you.</em></h1><p>Everything you need to manage today.<br>And a little help to plan tomorrow.</p></div><div class="auth-preview"><div class="row between"><span class="eyebrow">Your everyday account</span>${icon('wallet')}</div><strong>€8,420.50</strong><small>Fictional available balance</small><div class="auth-preview-actions"><span>${icon('send')}Send</span><span>${icon('card')}Cards</span><span>${icon('loan')}Loans</span></div><div class="auth-float">${icon('check')} Your demo transfer is complete</div></div><div class="auth-foot">ProCredit-inspired design · Independent prototype<br>No real accounts, payments or signatures.</div></section><section class="auth-main"><div class="auth-box">${brand()}<div class="row between"><span class="concept-tag"><span></span>Interactive concept</span><button class="textbtn" onclick="authHelp()">Need help?</button></div><div class="auth-tabs"><button class="${authTab==='login'?'active':''}" onclick="switchAuth('login')">Sign in</button><button class="${authTab==='register'?'active':''}" onclick="switchAuth('register')">Create demo profile</button></div>${authTab==='login'?loginForm():authTab==='reset'?resetForm():registerForm()}<div class="auth-safety">${icon('shield')}<span>Use fictional information only. No information is sent to a bank.</span></div></div></section></div>`}
function loginForm(){return `<h2>Hello again.</h2><p class="muted">Your finances. A little clearer.</p><form id="login-form"><label>Demo email<input type="email" name="email" value="demo@bimi.test" autocomplete="off" required></label><label>Demo password<span class="password-field"><input type="password" id="demo-password" name="password" value="Bimi2026!" autocomplete="off" required><button type="button" class="icon-button" aria-label="Show demo password" onclick="const p=$('#demo-password');p.type=p.type==='password'?'text':'password'">${icon('eye')}</button></span></label><div class="row between"><span class="fieldhelp">Sample credentials are ready to use.</span><button type="button" class="textbtn" onclick="switchAuth('reset')">Forgot password?</button></div><div id="form-error" class="error hidden" role="alert"></div><button class="btn" type="submit">Sign in to demo ${icon('chevron')}</button></form><div class="or-divider"><span>or explore without signing in</span></div><button class="btn secondary" style="width:100%" onclick="enterDemo()">Explore the platform ${icon('arrow')}</button><div class="auth-trust">${icon('lock')} Browser-only demo <span>•</span> No real bank connection</div>`}
function authHelp(){openDialog('About this demo',`<p class="muted">Select <strong>Explore the platform</strong> to try all features without registration.</p><div class="summary-line"><span>Demo email</span><strong>demo@bimi.test</strong></div><div class="summary-line"><span>Demo password</span><strong>Bimi2026!</strong></div><div class="notice">Every verification or signing code in this demo is <strong>123456</strong>. No SMS or email is sent.</div>`)}

// Source: src/features/dashboard.js
function bankcard(frozen=false,authCard=false){return `<div class="bankcard ${frozen?'frozen':''}"><div class="row between"><div class="card-wordmark">Bimi<span>ProCredit-inspired concept</span></div><span class="card-type">DEBIT</span></div><div class="card-chip" aria-hidden="true"><span></span></div><div class="cardnum">${cardReveal&&!authCard?'9999 0000 0000 4821':'•••• &nbsp; •••• &nbsp; •••• &nbsp; 4821'}</div><div class="row between"><div><div class="eyebrow">${authCard?'ERA KRASNIQI':esc(state.name.toUpperCase())}</div><small>12/29 <span style="margin-left:10px">${frozen?'FROZEN':'DEMO CARD'}</span></small></div><div class="mastercard" aria-label="Illustrative payment card"></div></div></div>`}
function monthTx(){const month=localDate().slice(0,7);return state.tx.filter(t=>t.date.startsWith(month)&&t.kind!=='own')}
function cashTotals(list=monthTx()){return {incoming:list.filter(t=>t.amount>0).reduce((n,t)=>n+t.amount,0),outgoing:-list.filter(t=>t.amount<0).reduce((n,t)=>n+t.amount,0)}}
function category(t){return t.category||(t.name.includes('KESCO')?'Bills':t.name.includes('Meridian')?'Shopping':t.name.includes('Soma')?'Food & drink':t.desc.includes('fee')||t.name.includes('fee')?'Fees':t.amount>0?'Money in':'Transfers')}
function txRows(list,limit){return (limit?list.slice(0,limit):list).map(t=>`<button class="tx" onclick="transactionDialog('${esc(t.id)}')"><span class="tx-icon ${t.amount>0?'incoming':t.kind==='card'?'purchase':''}">${icon(t.amount>0?'down':t.kind==='card'?'store':t.kind==='own'?'swap':'send')}</span><span class="tx-name"><strong>${esc(t.name)}</strong><small>${esc(t.desc)}</small></span><span class="tx-status"><span class="status-dot"></span>Completed</span><span class="txvalue ${t.amount>0?'in':''}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))}<small>${dateText(t.date)}</small></span><span class="tx-chevron">${icon('chevron')}</span></button>`).join('')||`<div class="empty">${icon('search')}<h3>No matching transactions</h3><p>Try another search, type or date range.</p></div>`}
function dashboard(){const cash=cashTotals(),bens=state.beneficiaries.slice(0,4),latest=state.loans.at(-1);return `${pagehead('Good to see you, '+esc(state.name.split(' ')[0])+'.','Here’s where things stand with your money today.',`<button class="btn" onclick="newPayment()">${icon('plus')} New payment</button>`)}<div class="overview-layout"><div class="overview-main stack"><section class="account-overview panel"><div class="panel-head"><div class="row"><h2>Your accounts</h2><span class="count-label">2 accounts · EUR</span></div><button class="icon-button" onclick="hideBalances=!hideBalances;render()" aria-label="${hideBalances?'Show':'Hide'} balances" aria-pressed="${hideBalances}">${icon('eye')}</button></div><div class="account-tiles"><button class="account-tile everyday" onclick="accountTab='everyday';goto('accounts')"><div class="row between"><span class="account-symbol">${icon('wallet')}</span><span class="pill">● Active</span></div><div class="tile-caption">Everyday account</div><strong>${masked(state.balance)}</strong><small>Available balance</small><div class="tile-bottom"><span>•••• 0000 · EUR</span>${icon('arrow')}</div></button><button class="account-tile savings" onclick="accountTab='savings';goto('accounts')"><div class="row between"><span class="account-symbol">${icon('spark')}</span><span class="account-caption">SAVE FOR TOMORROW</span></div><div class="tile-caption">Savings account</div><strong>${masked(state.savings)}</strong><small>Your savings balance</small><div class="tile-bottom"><span>•••• 0004 · EUR</span>${icon('arrow')}</div></button></div><div class="account-totals"><span>Total across your accounts</span><strong>${masked(state.balance+state.savings)}</strong><button class="textbtn" onclick="goto('accounts')">Account details ${icon('chevron')}</button></div></section><section class="quick-strip"><button onclick="newPayment()"><span>${icon('send')}</span><strong>Send money</strong></button><button onclick="transferTab='request';goto('transfers')"><span>${icon('down')}</span><strong>Request money</strong></button><button onclick="transferTab='bills';goto('transfers')"><span>${icon('file')}</span><strong>Pay a bill</strong></button><button onclick="ownTransferDialog()"><span>${icon('swap')}</span><strong>Between accounts</strong></button><button onclick="statement()"><span>${icon('download')}</span><strong>Statements</strong></button></section><section class="panel recipient-panel"><div class="panel-head"><div><h2>Send again</h2><small class="muted">A familiar face. Fewer steps.</small></div><button class="textbtn" onclick="beneficiariesDialog()">Manage ${icon('chevron')}</button></div><div class="recipient-list">${bens.map((b,i)=>`<button onclick="payBeneficiary(${i})"><span class="recipient-avatar ${b.color||'peach'}">${initials(b.name)}</span><strong>${esc(b.name.split(' ')[0])}</strong><small>•••• ${esc(b.iban.slice(-4))}</small></button>`).join('')}<button onclick="addBeneficiaryDialog()"><span class="recipient-avatar add">${icon('plus')}</span><strong>Add recipient</strong><small>Save for next time</small></button></div></section><section class="panel transaction-panel"><div class="panel-head"><div><h2>Latest activity</h2><small class="muted">Every payment, easy to find.</small></div><button class="textbtn" onclick="goto('activity')">View all activity ${icon('chevron')}</button></div><div class="tx-head"><span>TRANSACTION</span><span>STATUS</span><span>AMOUNT</span></div>${txRows(state.tx,5)}</section></div><aside class="overview-aside stack"><section class="panel card-widget"><div class="panel-head"><h2>Your debit card</h2><span class="pill ${state.card.frozen?'warn':''}">${state.card.frozen?'Frozen':'Active'}</span></div>${bankcard(state.card.frozen)}<div class="card-shortcuts"><button onclick="freezeCard()">${icon(state.card.frozen?'check':'snow')} ${state.card.frozen?'Unfreeze':'Freeze'}</button><button onclick="goto('cards')">${icon('settings')} Card settings</button></div></section><section class="panel cashflow-panel"><div class="panel-head"><h2>This month</h2><span class="small-label">${new Date().toLocaleDateString('en-GB',{month:'short',year:'numeric'})}</span></div><div class="cashflow-metric"><span class="roundicon incoming">${icon('down')}</span><div><small>Money in</small><strong>${masked(cash.incoming)}</strong></div><span class="flow-dot positive"></span></div><div class="cashflow-metric"><span class="roundicon outgoing">${icon('arrow')}</span><div><small>Money out</small><strong>${masked(cash.outgoing)}</strong></div><span class="flow-dot negative"></span></div><div class="cashflow-bar" aria-label="Incoming ${money(cash.incoming)}, outgoing ${money(cash.outgoing)}"><span style="width:${cash.incoming+cash.outgoing?cash.incoming/(cash.incoming+cash.outgoing)*100:50}%"></span></div><button class="textbtn" onclick="goto('activity')">Explore your activity ${icon('chevron')}</button></section><section class="loan-promo"><div class="promo-spark">${icon('loan')}</div><span class="eyebrow">A LITTLE HELP, A BIG NEXT STEP.</span><h2>${latest?'Your plans are moving.':'Make room for your next plan.'}</h2><p>${latest?`${money(latest.payment)} monthly instalment on your latest demo loan.`:'A personal loan with clear costs and an application you can complete here.'}</p><button class="btn" onclick="${latest?"goto('loans')":"startLoan()"}">${latest?'View my loans':'Explore personal loans'} ${icon('arrow')}</button><small>Illustrative offers · No real credit decision</small></section></aside></div>`}

// Source: src/features/accounts.js
function accounts(){const saving=accountTab==='savings',amount=saving?state.savings:state.balance;return `${pagehead('A clear view of your accounts.','The details you need, without the searching.',`<button class="btn secondary" onclick="statement()">${icon('download')} Download statement</button>`)}<div class="segmented account-segment"><button class="${!saving?'active':''}" onclick="accountTab='everyday';render()">${icon('wallet')} Everyday account</button><button class="${saving?'active':''}" onclick="accountTab='savings';render()">${icon('spark')} Savings account</button></div><div class="two-col"><div class="stack"><section class="panel account-detail"><span class="eyebrow muted">${saving?'SAVINGS':'EVERYDAY'} · EUR</span><div class="hero-number">${money(amount)}</div><span class="muted">${saving?'Savings balance':'Available balance'}</span><div class="divider"></div><div class="summary-line"><span>Account holder</span><strong>${esc(state.name)}</strong></div><div class="summary-line"><span>Demo IBAN</span><strong>XK05 0000 0000 0000 ${saving?'0004':'0000'}</strong></div><div class="summary-line"><span>Currency</span><strong>Euro · EUR</strong></div><div class="summary-line"><span>Account status</span><span class="pill">Active · demo</span></div><div class="formactions"><button class="btn secondary" onclick="accountConfirmation('${saving?'Savings':'Everyday'}')">${icon('download')} Account confirmation</button><button class="btn" onclick="ownTransferDialog()">${icon('swap')} Move money</button></div></section><section class="panel"><div class="panel-head"><h2>${saving?'Transfers to and from savings':'Everyday account activity'}</h2><button class="textbtn" onclick="goto('activity')">View all →</button></div>${txRows(saving?state.tx.filter(t=>t.kind==='own'):state.tx,6)}</section></div><aside class="panel insight"><div class="roundicon">${icon('help')}</div><h2 style="margin-top:15px">Your money, in the right place.</h2><p>Move fictional funds between your accounts instantly in this demo. There is no transfer fee between your own accounts.</p><button class="textbtn" onclick="ownTransferDialog()">Make an internal transfer ${icon('arrow')}</button></aside></div>`}
function accountConfirmation(type){download('Bimi_Demo_Account_Confirmation.txt',`DEMO ONLY — NOT A BANK DOCUMENT\n\nAccount holder: ${state.name}\nAccount: ${type}\nCurrency: EUR\nDemo IBAN: XK05 0000 0000 0000 ${type==='Savings'?'0004':'0000'}\nIssued: ${localDate()}\nIndependent ProCredit-inspired concept. Not affiliated with ProCredit Bank.`)}

// Source: src/features/transfers.js
function newPayment(){transferTab='send';goto('transfers')}
function transfers(){let intro=pagehead('Payments, without the extra steps.','Send, request or pay a bill. Everything starts here.');const tabs=`<div class="payment-tabs" role="group" aria-label="Payment types">${[['send','send','Send money'],['request','down','Request money'],['bills','file','Pay bills'],['recipients','user','Saved recipients']].map(([key,i,title])=>`<button class="${transferTab===key?'active':''}" onclick="transferTab='${key}';transferStage=0;transfer=null;render()">${icon(i)} ${title}</button>`).join('')}</div>`;
if(transferTab==='request')return intro+tabs+requestPage();if(transferTab==='bills')return intro+tabs+billsPage();if(transferTab==='recipients')return intro+tabs+beneficiariesPage();
let html=baseTransfers();html=html.slice(html.indexOf('<div class="two-col">'));if(transferStage===0){const picker=`<div class="saved-picker"><div class="row between"><small class="muted">CHOOSE A SAVED RECIPIENT</small><button class="textbtn" onclick="addBeneficiaryDialog()">${icon('plus')} Add new</button></div><div class="saved-chips">${state.beneficiaries.slice(0,4).map((b,i)=>`<button onclick="fillBeneficiary(${i})"><span class="avatar ${b.color||''}">${initials(b.name)}</span>${esc(b.name.split(' ')[0])}</button>`).join('')}</div></div>`;html=html.replace('<form id="transfer-form"',picker+'<form id="transfer-form"').replace('value="Arben Berisha"','placeholder="Enter recipient name"').replace('value="XK05 0000 0000 0000 0001"','placeholder="XK05 0000 0000 0000 0001"');html=html.replace('<div id="form-error"',`<label class="check"><input name="saveRecipient" type="checkbox"><span>Save this recipient for next time</span></label><div class="live-transfer-cost" id="transfer-estimate">Enter an amount to see the estimated total.</div><div id="form-error"`)}return intro+tabs+`<div class="transfer-progress">${['Enter details','Review payment','Approve'].map((s,i)=>`<span class="${transferStage===i?'active':transferStage>i?'done':''}"><b>${transferStage>i?'✓':i+1}</b>${s}</span>`).join('')}</div>`+html;
}
function fillBeneficiary(i){const b=state.beneficiaries[i],f=$('#transfer-form');if(!b||!f)return;f.elements.name.value=b.name;f.elements.iban.value=b.iban;f.elements.amount.focus();toast('Recipient details filled in.')}
function payBeneficiary(i){newPayment();fillBeneficiary(i)}
function beneficiariesPage(){return `<section class="panel"><div class="panel-head"><div><h2>Your saved recipients</h2><small class="muted">${state.beneficiaries.length} people and accounts, ready when you need them.</small></div><button class="btn" onclick="addBeneficiaryDialog()">${icon('plus')} Add recipient</button></div><div class="beneficiary-grid">${state.beneficiaries.map((b,i)=>`<div class="beneficiary-tile"><div class="row"><span class="recipient-avatar ${b.color||'peach'}">${initials(b.name)}</span><div><h3>${esc(b.name)}</h3><small class="muted">Demo account · •••• ${esc(b.iban.slice(-4))}</small></div></div><div class="row between" style="margin-top:24px"><button class="textbtn" onclick="removeBeneficiary(${i})">Remove</button><button class="btn secondary" onclick="payBeneficiary(${i})">Send money ${icon('arrow')}</button></div></div>`).join('')||'<div class="empty">Add your first sample recipient.</div>'}</div></section>`}
function requestPage(){return `<div class="two-col"><section class="panel"><div class="panel-head"><div><span class="eyebrow muted">REQUEST TO PAY</span><h2 style="margin-top:6px">Let them know what’s due.</h2></div><div class="roundicon">${icon('down')}</div></div><form id="request-form" class="stack"><div class="formgrid"><label class="wide">Who are you requesting from?<input name="payer" required placeholder="Fictional name" maxlength="70"></label><label>Amount (EUR)<input type="number" name="amount" min="0.01" max="10000" step="0.01" required placeholder="0.00"></label><label>What is it for?<input name="note" required placeholder="Dinner, shared expenses…" maxlength="100"></label></div><div class="notice">This creates a request in the demo. No notification or payment link is sent to another person.</div><div id="form-error" class="error hidden" role="alert"></div><button class="btn" type="submit" style="justify-self:end">Create demo request ${icon('arrow')}</button></form></section><aside class="panel"><h2>Recent requests</h2><div class="request-list">${state.requests.map(r=>`<div class="request-item"><div class="row between"><strong>${esc(r.payer)}</strong><strong>${money(r.amount)}</strong></div><small class="muted">${esc(r.note)} · ${dateText(r.date)}</small><div class="row between"><span class="pill warn">Pending · demo</span><button class="textbtn" onclick="downloadRequest('${r.id}')">${icon('download')} Details</button></div></div>`).join('')||'<div class="empty">No requests yet.<p>Create one to see it here.</p></div>'}</div></aside></div>`}
function downloadRequest(id){const r=state.requests.find(x=>x.id===id);if(r)download('Bimi_Demo_Payment_Request.txt',`DEMO REQUEST — NO PAYMENT LINK\n\nReference: ${r.id}\nRequested from: ${r.payer}\nAmount: ${money(r.amount)}\nReason: ${r.note}\nStatus: Pending (demo)\nNo message was sent.`)}
const billers=[{name:'KESCO',label:'Electricity',icon:'spark',iban:'XK050000000000000011',sample:62.4},{name:'KRU Prishtina',label:'Water',icon:'home',iban:'XK050000000000000012',sample:18.9},{name:'Telekom',label:'Phone & internet',icon:'globe',iban:'XK050000000000000013',sample:24.9}];
function billsPage(){return `<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Everyday bills, taken care of.</h2><small class="muted">Choose a sample biller to start a payment.</small></div></div><div class="biller-grid">${billers.map((b,i)=>`<button class="biller-tile" onclick="billDialog(${i})"><span class="roundicon">${icon(b.icon)}</span><strong>${b.name}</strong><small>${b.label}</small><span class="textbtn">Pay bill ${icon('arrow')}</span></button>`).join('')}</div><div class="notice" style="margin-top:22px">Biller names are illustrative. All account numbers and invoices are fictional. No biller integration is connected.</div></section><aside class="panel"><h2>Before you pay</h2><div class="flow-list"><div class="flow-item"><span>1</span><div><strong>Choose the biller</strong><small>Select the service you want to pay.</small></div></div><div class="flow-item"><span>2</span><div><strong>Add the invoice reference</strong><small>Use a sample invoice, never real details.</small></div></div><div class="flow-item"><span>3</span><div><strong>Review and approve</strong><small>Check the full cost before confirmation.</small></div></div></div></aside></div>`}
function billDialog(i){const b=billers[i];openDialog('Pay '+b.name,`<p class="muted">Enter fictional invoice details for this sample bill.</p><form id="bill-form" class="stack"><label>Invoice reference<input name="invoice" required value="DEMO-2026-001" maxlength="60"></label><label>Amount (EUR)<input name="amount" type="number" required min="0.01" max="10000" step="0.01" value="${b.sample}"></label><button type="submit" class="btn">Continue to review ${icon('chevron')}</button></form>`);$('#bill-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);transfer={name:b.name,iban:b.iban,type:'Domestic transfer',amount:Number(d.get('amount')),fee:.5,note:'Invoice '+d.get('invoice')};if(transfer.amount+.5>state.balance)return toast('Insufficient demo balance.');transferTab='send';page='transfers';transferStage=1;closeDialog();render();}}

// Source: src/features/cards.js
function cards(){const c=state.card;let html=baseCards();html=html.replace('Your card. Your control.','Your card, exactly how you want it.').replace('Manage where and how your debit card can be used.','A single place to manage spending, limits and card security.');return html.replace('<h3 style="margin:25px 0 18px">Daily spending limits</h3>',`<div class="card-usage"><div class="row between"><h3>Online spending limit</h3><span>${money(c.web)} / day</span></div><div class="progress"><span style="width:${Math.min(100,c.web/100)}%"></span></div><small class="muted">A fictional limit setting, not actual card usage.</small></div><h3 style="margin:25px 0 18px">Daily spending limits</h3>`)}

// Source: src/features/loans.js
function startLoan(preset){loanView='application';page='loans';loanStage=0;showSchedule=false;loan={amount:10000,months:36,purpose:'Home improvement',income:1850,commitments:200,employment:'Employed',docs:false,...preset};render();window.scrollTo(0,0)}
function resumeLoan(){if(!state.loanDraft)return;loan={...state.loanDraft.loan};loanStage=Math.min(5,state.loanDraft.stage);loanView='application';page='loans';render();window.scrollTo(0,0)}
function loans(){if(loanView==='application'){let html=baseLoans();return `<button class="back-link" onclick="loanView='hub';render()">← Back to my loans</button>`+html.replace('<form id="loan-application" class="stack">',`<div class="loan-presets"><button onclick="setLoanPreset(5000,24)">€5,000 / 24 mo.</button><button onclick="setLoanPreset(10000,36)">€10,000 / 36 mo.</button><button onclick="setLoanPreset(20000,60)">€20,000 / 60 mo.</button></div><form id="loan-application" class="stack">`)}
const draft=state.loanDraft;return `${pagehead('Your next step starts here.','Explore a loan, continue your application or manage your agreements.',`<button class="btn" onclick="startLoan()">${icon('plus')} New application</button>`)}${draft?`<div class="resume-banner"><div class="row"><span class="roundicon">${icon('file')}</span><div><strong>You have an application in progress.</strong><p>${money(draft.loan.amount)} · ${draft.loan.months} months · Step ${draft.stage+1} of 7</p></div></div><button class="btn" onclick="resumeLoan()">Continue application ${icon('chevron')}</button></div>`:''}<div class="loan-hub-grid"><section class="loan-hero"><div><span class="eyebrow">PERSONAL LOAN · ILLUSTRATIVE OFFER</span><h2>Big plans.<br>Simple next steps.</h2><p>From a home improvement to a fresh start. Explore a payment that fits your budget, with every cost explained upfront.</p><button class="btn" onclick="startLoan()">Calculate my loan ${icon('arrow')}</button></div><div class="loan-hero-figure"><span>EXAMPLE MONTHLY PAYMENT</span><strong>${money(loanCalc({amount:10000,months:36,income:1850,commitments:200}).payment)}</strong><small>€10,000 over 36 months</small><div><b>6.90%</b><small>Fixed nominal interest p.a.</small></div><span class="pill">1% upfront fee · Demo pricing</span></div></section><section class="panel journey-panel"><span class="eyebrow muted">FROM START TO FINISH</span><h2>Know what comes next.</h2><div class="flow-list">${[['Your application','Choose the amount and tell us about income.'],['A clear offer','Review the payment, fees and schedule.'],['Agreement & signing','Read the document and simulate signing.'],['Money in your account','See fictional funds credited instantly.']].map((x,i)=>`<div class="flow-item"><span>${i+1}</span><div><strong>${x[0]}</strong><small>${x[1]}</small></div></div>`).join('')}</div></section></div><section class="panel" style="margin-top:24px"><div class="panel-head"><div><h2>My loans & agreements</h2><small class="muted">Your completed demo applications, together.</small></div><span class="count-label">${state.loans.length} ${state.loans.length===1?'loan':'loans'}</span></div>${state.loans.length?state.loans.map((l,i)=>`<div class="loan-record"><span class="roundicon">${icon('loan')}</span><div><strong>${esc(l.purpose)}</strong><small>${l.id} · ${dateText(l.signedAt.slice(0,10))}</small></div><div><strong>${money(l.amount)}</strong><small>Original principal</small></div><div><strong>${money(l.payment)} / mo.</strong><small>${l.months} instalments</small></div><span class="pill">Disbursed · demo</span><button class="btn secondary" onclick="loanDetailDialog(${i})">Details ${icon('chevron')}</button></div>`).join(''):`<div class="loan-empty"><span class="roundicon">${icon('file')}</span><div><h3>No demo loans yet.</h3><p class="muted">Complete an application to see its details and agreement here.</p></div><button class="textbtn" onclick="startLoan()">Explore a loan →</button></div>`}</section><div class="notice" style="margin-top:20px">All lending rates, eligibility rules and decisions are illustrative, and do not represent ProCredit Bank products or policies.</div>`}
function setLoanPreset(amount,months){const f=$('#loan-application');if(f){loan={...loan,amount,months,purpose:f.elements.purpose.value,employment:f.elements.employment.value,income:Number(f.elements.income.value)||1850,commitments:Number(f.elements.commitments.value)||0};render()}}
function loanDetailDialog(i){const l=state.loans[i];openDialog('Your demo loan',`<span class="pill">Disbursed · demo</span><div class="hero-number">${money(l.amount)}</div><p class="muted">${esc(l.purpose)} · ${l.id}</p><div class="summary-line"><span>Monthly instalment</span><strong>${money(l.payment)}</strong></div><div class="summary-line"><span>Term</span><strong>${l.months} months</strong></div><div class="summary-line"><span>First repayment</span><strong>${dateText(l.firstDate)}</strong></div><div class="summary-line"><span>Net disbursement</span><strong>${money(l.net)}</strong></div><div class="summary-line"><span>Signature record</span><strong>${esc(l.signedBy)} · simulated</strong></div><button class="btn" style="width:100%;margin-top:24px" onclick="downloadAgreement(state.loans[${i}])">${icon('download')} Download sample agreement</button>`)}
function downloadAgreement(signed=false){const l=typeof signed==='object'?signed:signed?state.loans.at(-1):loan;const html=`<!doctype html><html lang="en"><meta charset="utf-8"><title>Bimi • Sample loan agreement</title><style>body{font:15px/1.8 Arial,sans-serif;max-width:800px;margin:40px auto;padding:25px;color:#303238;border-top:6px solid #e36731}h3{color:#222}strong{font-weight:700}button{padding:10px 20px;margin:0 0 25px;background:#f4eee8;border:0;border-radius:8px}@media print{button{display:none}}</style><button onclick="print()">Print / Save as PDF</button>${agreementHTML(l,signed?l:null)}</html>`;download('Bimi_Sample_Loan_Agreement.html',html,'text/html')}

// Source: src/features/activity.js
function filteredTransactions(){return state.tx.filter(t=>{const q=activityQuery.toLowerCase();return (!q||(t.name+' '+t.desc+' '+t.id).toLowerCase().includes(q))&&(activityFilter==='all'||activityFilter==='in'&&t.amount>0||activityFilter==='out'&&t.amount<0||activityFilter==='card'&&t.kind==='card')&&(!activityFrom||t.date>=activityFrom)&&(!activityTo||t.date<=activityTo)})}
function activity(){const cash=cashTotals();return `${pagehead('Find every detail.','Search, filter and download your account activity.',`<button class="btn secondary" onclick="statement()">${icon('download')} Export all transactions</button>`)}<div class="activity-kpis"><div><span class="roundicon incoming">${icon('down')}</span><span><small>Money in this month</small><strong>${money(cash.incoming)}</strong></span></div><div><span class="roundicon outgoing">${icon('arrow')}</span><span><small>Money out this month</small><strong>${money(cash.outgoing)}</strong></span></div><div><span class="roundicon">${icon('history')}</span><span><small>Total transactions in demo</small><strong>${state.tx.length}</strong></span></div></div><section class="panel"><div class="panel-head"><h2>Transaction history</h2><span class="count-label" id="result-count">${filteredTransactions().length} results</span></div><div class="activity-tools"><label class="search-field">${icon('search')}<input id="activity-search" placeholder="Search name, reference or description" aria-label="Search transactions" value="${esc(activityQuery)}"></label><label>From<input id="activity-from" type="date" value="${activityFrom}" aria-label="From date"></label><label>To<input id="activity-to" type="date" value="${activityTo}" aria-label="To date"></label></div><div class="filter-chips">${[['all','All activity'],['in','Money in'],['out','Money out'],['card','Card payments']].map(([key,title])=>`<button class="${activityFilter===key?'active':''}" onclick="activityFilter='${key}';render()">${title}</button>`).join('')}<button class="clear-filter" onclick="activityFilter='all';activityQuery='';activityFrom='';activityTo='';render()">Clear filters</button></div><div id="activity-results">${txRows(filteredTransactions())}</div></section><div class="activity-bottom"><span>${icon('shield')} All entries are fictional demonstration data.</span><button class="textbtn" onclick="resetDemo()">Reset demo</button></div>`}
function updateActivity(){const list=filteredTransactions();$('#activity-results').innerHTML=txRows(list);$('#result-count').textContent=list.length+' results'}

// Source: src/features/support.js
function support(){return `${pagehead('A little support goes a long way.','Find answers or explore the in-app support experience.')}<div class="two-col"><div class="stack"><section class="panel"><div class="panel-head"><h2>How can we help?</h2><div class="roundicon">${icon('message')}</div></div><form id="support-form" class="stack"><label>Topic<select name="topic"><option>Payments & transfers</option><option>Cards & limits</option><option>Loan application</option><option>Access & profile</option></select></label><label>Your demo message<textarea name="message" rows="4" maxlength="1000" required placeholder="Use fictional details. What would you like help with?"></textarea></label><div class="notice">Messages are saved only in this browser session. Nothing is sent to ProCredit Bank or any support team.</div><button class="btn" type="submit" style="justify-self:end">Save demo message ${icon('message')}</button></form></section><section class="panel"><h2>Your saved messages</h2>${state.messages.map(m=>`<div class="saved-message"><div class="row between"><strong>${esc(m.topic)}</strong><span class="pill">Saved locally</span></div><p>${esc(m.message)}</p><small class="muted">${dateText(m.date)}</small></div>`).join('')||'<div class="empty">Your saved demo messages will appear here.</div>'}</section></div><aside class="panel"><h2>Quick answers</h2>${[['How do I approve a transfer?','Review your recipient, amount and fee, then enter the fixed demo code 123456. No SMS is sent.'],['Can I freeze my card?','Yes. Open Cards and select Freeze card. Unfreeze it whenever you want. This changes only the fictional card state.'],['How do I resume my loan?','Open Loans and select Continue application. Your draft is retained for this browser session.'],['Are these real banking services?','No. This is an independent design concept with fictional accounts, payments, lending and signatures.']].map(([q,a])=>`<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}</aside></div>`}

// Source: src/core/dialogs.js
function openDialog(title,html){const d=$('#app-dialog');if(d.open)d.close();d.innerHTML=`<div class="dialog-head"><div><span class="eyebrow muted">BIMI · CONCEPT DEMO</span><h2 id="dialog-title">${title}</h2></div><button class="icon-button" onclick="closeDialog()" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-content">${html}</div>`;d.showModal();d.onclick=e=>{if(e.target===d)closeDialog()};}
function closeDialog(){const d=$('#app-dialog');if(d?.open)d.close()}
function transactionDialog(id){const t=state.tx.find(x=>x.id===id);if(!t)return;openDialog('Transaction details',`<span class="pill">Completed · demo</span><div class="hero-number ${t.amount>0?'positive-text':''}" style="margin-top:15px">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))}</div><h3>${esc(t.name)}</h3><p class="muted">${esc(t.desc)}</p><div class="divider"></div><div class="summary-line"><span>Reference</span><strong>${esc(t.id)}</strong></div><div class="summary-line"><span>Date</span><strong>${dateText(t.date)}</strong></div><div class="summary-line"><span>Category</span><strong>${esc(category(t))}</strong></div><div class="summary-line"><span>Account</span><strong>Everyday · EUR</strong></div><div class="notice" style="margin-top:18px">This is a fictional transaction. No real funds moved.</div><button class="btn secondary" style="width:100%;margin-top:20px" onclick="downloadTransaction('${esc(t.id)}')">${icon('download')} Download details</button>`)}
function downloadTransaction(id){const t=state.tx.find(x=>x.id===id);if(t)download('Bimi_Demo_Transaction.txt',`DEMO ONLY — NOT A PAYMENT CONFIRMATION\n\n${t.name}\nAmount: ${money(t.amount)}\nReference: ${t.id}\nDate: ${t.date}\nDescription: ${t.desc}\nStatus: Completed (demo)`)}
function beneficiariesDialog(){transferTab='recipients';goto('transfers')}
function addBeneficiaryDialog(){openDialog('Save a recipient',`<p class="muted">Keep a fictional recipient ready for your next demo transfer.</p><form id="beneficiary-form" class="stack"><label>Full name<input name="name" required maxlength="70" placeholder="Recipient name"></label><label>Demo IBAN<input name="iban" required placeholder="XK05 0000 0000 0000 0001"></label><div id="dialog-error" class="error hidden" role="alert"></div><button class="btn" type="submit">Save recipient ${icon('check')}</button></form>`);$('#beneficiary-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),name=d.get('name').trim(),iban=d.get('iban').replace(/\s/g,'').toUpperCase();if(!name||!/^XK\d{18}$/.test(iban)||iban==='XK050000000000000000'){const x=$('#dialog-error');x.textContent='Enter a name and an XK demo IBAN with 18 digits, different from your own account.';x.classList.remove('hidden');return}if(state.beneficiaries.some(b=>b.iban===iban))return toast('This account is already saved.');state.beneficiaries.push({name,iban,color:['peach','lavender','mint'][state.beneficiaries.length%3]});save();closeDialog();render();toast('Recipient saved for this browser session.')}}
function removeBeneficiary(i){const b=state.beneficiaries[i];openDialog('Remove recipient?',`<p class="muted">Remove ${esc(b.name)} from your demo recipients?</p><div class="formactions"><button class="btn secondary" onclick="closeDialog()">Keep recipient</button><button class="btn" onclick="state.beneficiaries.splice(${i},1);save();closeDialog();render();toast('Recipient removed.')">Remove</button></div>`)}
function ownTransferDialog(){openDialog('Move money between accounts',`<p class="muted">Same owner. No fee. Fictional funds only.</p><form id="own-transfer-form" class="stack"><label>Direction<select name="direction"><option value="save">Everyday → Savings</option><option value="withdraw">Savings → Everyday</option></select></label><div class="own-balances"><span>Everyday <strong>${money(state.balance)}</strong></span><span>Savings <strong>${money(state.savings)}</strong></span></div><label>Amount (EUR)<input name="amount" type="number" min="0.01" step="0.01" required placeholder="0.00"></label><div id="dialog-error" class="error hidden" role="alert"></div><button class="btn" type="submit">Move demo funds ${icon('swap')}</button></form>`);$('#own-transfer-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),amount=Number(d.get('amount')),saving=d.get('direction')==='save',available=saving?state.balance:state.savings;if(!Number.isFinite(amount)||amount<=0||amount>available){$('#dialog-error').textContent='Enter an amount within the available source balance.';$('#dialog-error').classList.remove('hidden');return}state.balance=Math.round((state.balance+(saving?-amount:amount))*100)/100;state.savings=Math.round((state.savings+(saving?amount:-amount))*100)/100;state.tx.unshift({id:reference('OWN'),date:localDate(),name:saving?'Transfer to savings':'Transfer from savings',desc:'Between own accounts · no fee',amount:saving?-amount:amount,kind:'own',category:'Own accounts'});save();closeDialog();render();toast('Fictional funds moved between your accounts.')}}
function notificationsDialog(){openDialog('Your notifications',`<div class="notification-list"><div class="notification-item"><span class="roundicon">${icon('shield')}</span><div><strong>Your demo workspace is ready.</strong><p>All activity stays in this browser session.</p><small>Concept information</small></div></div>${state.tx.slice(0,4).map(t=>`<button class="notification-item" onclick="transactionDialog('${esc(t.id)}')"><span class="roundicon">${icon(t.amount>0?'down':'send')}</span><span><strong>${t.amount>0?'Money received':'Payment completed'}</strong><p>${esc(t.name)} · ${money(Math.abs(t.amount))}</p><small>${dateText(t.date)} · demo</small></span></button>`).join('')}${state.requests.slice(0,2).map(r=>`<div class="notification-item"><span class="roundicon">${icon('message')}</span><div><strong>Payment request created</strong><p>${money(r.amount)} from ${esc(r.payer)} · pending</p><small>Saved locally · not sent</small></div></div>`).join('')}</div>`)}
function profileDialog(){openDialog('Profile & preferences',`<div class="profile-summary"><span class="recipient-avatar peach">${initials(state.name)}</span><div><h2>${esc(state.name)}</h2><p class="muted">${esc(state.email)}</p><span class="pill">Demo profile</span></div></div><div class="summary-line"><span>Customer segment</span><strong>Personal banking</strong></div><div class="summary-line"><span>Interface</span><strong>English · EUR</strong></div><div class="notice" style="margin:18px 0">For privacy, passwords are not persisted. Reloading returns to the sign-in screen; fictional balances remain for this session.</div><div class="formactions"><button class="btn secondary" onclick="closeDialog();goto('support')">${icon('help')} Help & support</button><button class="btn" onclick="closeDialog();logout()">Sign out ${icon('logout')}</button></div>`)}
function searchDialog(){openDialog('What would you like to do?',`<label class="search-field dialog-search">${icon('search')}<input id="service-search" aria-label="Search banking services" placeholder="Try transfers, card limits or loans…"></label><div id="service-results"></div>`);const options=[['Send money','Domestic and internal transfers',"newPayment()"],['Pay a bill','Electricity, water, phone & internet',"transferTab='bills';goto('transfers')"],['Request money','Create a local demo payment request',"transferTab='request';goto('transfers')"],['Card limits & security','Freeze your card or change limits',"goto('cards')"],['Apply for a loan','Calculator, offer, agreement and signing',"startLoan()"],['My loan agreements','Continue applications or view completed loans',"goto('loans')"],['Statements & transaction history','Find and export your activity',"goto('activity')"],['Account details','View demo IBANs and balances',"goto('accounts')"],['Help & support','Find answers or save a demo message',"goto('support')"]];const fill=()=>{const q=$('#service-search').value.toLowerCase();$('#service-results').innerHTML=options.filter(x=>(x[0]+' '+x[1]).toLowerCase().includes(q)).map(([t,d,a])=>`<button class="service-result" onclick="closeDialog();${a}"><span><strong>${t}</strong><small>${d}</small></span>${icon('chevron')}</button>`).join('')||'<div class="empty">No matching services. Try another word.</div>'};$('#service-search').oninput=fill;fill();$('#service-search').focus()}

// Source: src/core/events.js
function bind(){baseBind();const draftForm=$('#loan-application');if(draftForm)draftForm.addEventListener('input',()=>{const d=new FormData(draftForm);for(const k of ['amount','months','income','commitments']){const v=Number(d.get(k));if(Number.isFinite(v))loan[k]=v}loan.purpose=d.get('purpose');loan.employment=d.get('employment');state.loanDraft={loan:{...loan},stage:0};save()});const form=$('#transfer-form');if(form){form.addEventListener('submit',()=>{if(transferStage===1&&form.elements.saveRecipient?.checked&&transfer&&!state.beneficiaries.some(b=>b.iban===transfer.iban)){state.beneficiaries.push({name:transfer.name,iban:transfer.iban,color:'peach'});save()}});const estimate=()=>{const a=Number(form.elements.amount.value)||0,fee=form.elements.type.value==='Domestic transfer'?.5:0,x=$('#transfer-estimate');if(x)x.innerHTML=a?`<span>Amount ${money(a)} + fee ${money(fee)}</span><strong>Total ${money(a+fee)}</strong>`:'Enter an amount to see the estimated total.'};form.elements.amount.addEventListener('input',estimate);form.elements.type.addEventListener('change',estimate);estimate()}
 const bindForm=(id,fn)=>{const f=$(id);if(f)f.addEventListener('submit',e=>{e.preventDefault();fn(new FormData(f))})};
 bindForm('#request-form',d=>{const payer=d.get('payer').trim(),note=d.get('note').trim(),amount=Number(d.get('amount'));if(!payer||!note||!Number.isFinite(amount)||amount<=0||amount>10000)return error('Enter a name, reason and amount between €0.01 and €10,000.');state.requests.unshift({id:reference('REQ'),payer,note,amount,date:localDate()});save();render();toast('Demo request created. No message was sent.')});
 bindForm('#support-form',d=>{const message=d.get('message').trim();if(!message)return;state.messages.unshift({id:reference('MSG'),topic:d.get('topic'),message,date:localDate()});save();render();toast('Demo message saved locally.')});
 for(const [id,key] of [['#activity-search','query'],['#activity-from','from'],['#activity-to','to']])if($(id))$(id).addEventListener('input',e=>{if(key==='query')activityQuery=e.target.value;else if(key==='from')activityFrom=e.target.value;else activityTo=e.target.value;updateActivity()});
}


// Source: src/features/guide.js
// A guided tour links directly to each supported journey; progress reflects this session only.
function journeyGuide() {
 const steps = [
  ['accounts', 'wallet', '1. Get to know your accounts', 'View balances, demo IBANs and account confirmations.'],
  ['transfers', 'send', '2. Send your first demo transfer', 'Choose a recipient, review the fee and approve with 123456.'],
  ['cards', 'card', '3. Set your card preferences', 'Freeze or unfreeze the card, control purchases and set daily limits.'],
  ['loans', 'loan', '4. Explore a loan from start to finish', 'Calculate → documents → assessment → offer → agreement → simulated signing.']
 ];
 openDialog('Your banking, step by step', `<p class="muted">Choose where to start. Every journey uses fictional information.</p><div class="flow-list">${steps.map(([route, glyph, title, description]) => `<button class="service-result" onclick="closeDialog();goto('${route}')"><span class="roundicon">${icon(glyph)}</span><span><strong>${title}</strong><small>${description}</small></span>${icon('chevron')}</button>`).join('')}</div><div class="notice">Demo approvals and signatures use <strong>123456</strong>. No SMS is sent and no funds move.</div>`);
}

